from pathlib import Path
from html import escape
from format_lecon import paras
from medicaments import quote
def hydrocortisone(l):
 d=paras('Hydrocortison-POS 1% est une pommade ophtalmique contenant 10 mg/g d’acétate d’hydrocortisone, tube de 2,5 g, autorisation suisse 63125. Elle réduit les réactions inflammatoires et allergiques. Cette spécialité n’est ni une crème cutanée quelconque ni une préparation à appliquer empiriquement sur toute paupière rouge.',
 'La notice de janvier 2018 couvre les inflammations allergiques non infectieuses des paupières et de la conjonctive. Le contexte de cette fenêtre est une atteinte palpébrale allergique examinée chez l’adulte. Une dermatite purement irritative n’est pas présentée comme indication explicitement nommée.')
 d+=quote('63125',['Pour le traitement stéroïdien','La durée du traitement ne devrait pas dépasser','Sauf prescription contraire, appliquer','En cas de traitement supplémentaire','La sécurité et l\'efficacité'])
 d+=paras('La dose officielle adulte est un filet d’environ 1 cm deux à trois fois par jour, puis une à deux fois par jour lorsque l’effet est obtenu. Pour une maladie de la paupière, le prescripteur précise l’application sur la paupière touchée ; la possibilité conjonctivale de la notice ne signifie pas qu’une dermatite cutanée impose de traiter l’intérieur de l’œil.',
 'La durée doit être la plus courte possible et ne devrait pas dépasser deux semaines selon cette notice. Ce plafond n’est pas un objectif de durée ni une autorisation de renouveler sans contrôle. L’efficacité et la tolérance déterminent la réduction, l’arrêt et le contrôle prévu par le prescripteur.',
 'L’utilisation avant 18 ans n’est pas recommandée par cette spécialité. Les pratiques pédiatriques décrites pour d’autres hydrocortisones dans des documents étrangers ne lèvent pas cette restriction. Aucun palier de dose rénale ou hépatique n’est fourni pour cette pommade ; une adaptation systémique ne se transpose pas en longueur de filet.')
 lines=(Path(__file__).resolve().parents[1]/'evidence/AIPS_63125.txt').read_text().splitlines();a=lines.index('Contre-indications')+1;b=lines.index('Mises en garde et précautions',a)
 d+='<h3>Contre-indications officielles</h3><blockquote><p>« '+escape(' '.join(lines[a:b]))+' »</p></blockquote>'
 d+=paras('Écarter infection oculaire, herpès actif, ulcération ou blessure cornéenne et glaucome avant prescription. Le produit peut masquer ou aggraver une infection. Un antécédent d’herpès exige un avis spécialisé ; il ne permet pas de lever la contre-indication d’une atteinte active en ajoutant soi-même un antiviral.')
 d+=quote('63125',['La pression intraoculaire doit','En présence de maladies conduisant','La lanoline peut','L\'administration de collyres mydriatiques'])
 d+=paras('Une surveillance de la pression intraoculaire est demandée à intervalles fréquents par la notice. L’état de la cornée est contrôlé, notamment si elle est fragile. Les risques comprennent hypertension oculaire/glaucome, cataracte, retard de cicatrisation et infection. Une vision floue persistante ou un nouveau symptôme visuel nécessite un examen.',
 'La lanoline peut elle-même provoquer une dermatite de contact. Cette présence est particulièrement pertinente lorsque l’indication discutée est un eczéma allergique. Une réaction au traitement impose de réévaluer le produit, ses excipients et le diagnostic.',
 'Les collyres dilatant la pupille peuvent majorer le risque d’hyperpression. Les traitements du glaucome peuvent aussi être moins efficaces, mais un ajustement ne remplace pas la contre-indication de glaucome de cette notice. Éviter les lentilles pendant l’utilisation.')
 d+='<h3>Grossesse et allaitement : notice propre au produit</h3>'
 d+=quote('63125',['Il n\'existe pas d\'études contrôlées','Un traitement à long terme par glucocorticoïdes','Les corticostéroïdes traversent','Si les glucocorticoïdes sont utilisés','Les glucocorticoïdes passent'])
 d+=paras('Pendant la grossesse, usage seulement en cas de nécessité absolue, à dose et durée minimales. Une exposition en fin de grossesse nécessite une attention au nouveau-né selon la notice. Pendant l’allaitement, l’indication est strictement définie et la notice demande une interruption si des doses plus élevées sont nécessaires, sans donner de seuil chiffré. Ce seuil ne doit pas être inventé ; le choix d’une alternative se discute.',
 'Les formulations inhabituelles de la citation officielle sont conservées. Elles ne sont pas réinterprétées comme preuve d’absence de risque. Toute prescription tient compte du bénéfice attendu pour cette petite surface et de la possibilité d’éviter le produit responsable.')
 d+=quote('63125',['Le médicament ne doit pas être utilisé','Afin de maintenir la stérilité'])
 d+=paras('Ne pas contaminer l’embout. Espacer d’au moins quinze minutes les autres préparations ophtalmiques et appliquer cette pommade en dernier selon sa notice. Les vingt-huit jours après ouverture concernent la conservation, pas la durée de corticothérapie. Attendre une vision nette avant conduite ; une gêne durable demande un contrôle.')
 return l.subwindow('hydrocortisone','Hydrocortisone : spécialité suisse et surveillance',d,(32,))
